mapper.select:
SELECT k.content::text AS content, 1 - (k.embedding <=> CAST(#{queryVec} AS vector)) AS score, k.document_id, k.id AS chunk_id, k.source_version FROM knowledge_chunk_values k WHERE k.tenant_id = CAST(#{tenantId} AS bigint) AND k.kb_id = CAST(#{kbId} AS bigint) AND k.embedding IS NOT NULL AND vector_dims(k.embedding) = vector_dims(CAST(#{queryVec} AS vector))
AND 1 - (k.embedding <=> CAST(#{queryVec} AS vector)) >= #{threshold}
AND EXISTS (SELECT 1 FROM nw_knowledge_bases b WHERE b.id = k.kb_id AND b.status = 'active') ORDER BY k.embedding <=> CAST(#{queryVec} AS vector) LIMIT #{topK}

SELECT k.content::text AS content, 1 - (k.embedding <=> CAST(#{queryVec} AS vector)) AS score, k.document_id, k.id AS chunk_id, k.source_version FROM knowledge_chunk_values k WHERE k.tenant_id = CAST(#{tenantId} AS bigint) AND k.kb_id = CAST(#{kbId} AS bigint) AND k.source_version = #{sourceVersion} AND k.embedding IS NOT NULL AND vector_dims(k.embedding) = vector_dims(CAST(#{queryVec} AS vector))
AND 1 - (k.embedding <=> CAST(#{queryVec} AS vector)) >= #{threshold}
AND EXISTS (SELECT 1 FROM nw_knowledge_bases b WHERE b.id = k.kb_id AND b.status = 'active') ORDER BY k.embedding <=> CAST(#{queryVec} AS vector) LIMIT #{topK}

SELECT k.content::text AS content, 1 - (k.embedding <=> CAST(#{queryVec} AS vector)) AS score, k.document_id, k.id AS chunk_id, k.source_version FROM knowledge_chunk_values k WHERE k.tenant_id = CAST(#{tenantId} AS bigint) AND k.kb_id = CAST(#{kbId} AS bigint)
AND k.source_version IN
#{version}
AND FALSE
AND k.embedding IS NOT NULL AND vector_dims(k.embedding) = vector_dims(CAST(#{queryVec} AS vector))
AND 1 - (k.embedding <=> CAST(#{queryVec} AS vector)) >= #{threshold}
AND EXISTS (SELECT 1 FROM nw_knowledge_bases b WHERE b.id = k.kb_id AND b.status = 'active') ORDER BY k.embedding <=> CAST(#{queryVec} AS vector) LIMIT #{topK}
